#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> tiles(3);
    for (string& tile : tiles) cin >> tile;

    if (tiles[0] == tiles[1] && tiles[1] == tiles[2]) {
        cout << 0 << '\n';
        return 0;
    }

    for (char suit : {'m', 'p', 's'}) {
        vector<int> ranks;
        for (const string& tile : tiles)
            if (tile[1] == suit)
                ranks.push_back(tile[0] - '0');

        if (ranks.size() == 3) {
            sort(ranks.begin(), ranks.end());
            if (ranks[0] + 1 == ranks[1] && ranks[1] + 1 == ranks[2]) {
                cout << 0 << '\n';
                return 0;
            }
        }
    }

    for (int i = 0; i < 3; ++i) {
        for (int j = i + 1; j < 3; ++j) {
            if (tiles[i] == tiles[j] ||
                (tiles[i][1] == tiles[j][1] &&
                 abs(tiles[i][0] - tiles[j][0]) <= 2)) {
                cout << 1 << '\n';
                return 0;
            }
        }
    }

    cout << 2 << '\n';
    return 0;
}
